  var NAMES = Object.keys(DATA);
  var FLAT = null;

  function categories() { return NAMES.slice(); }

  function byCategory(name) {
    return Object.prototype.hasOwnProperty.call(DATA, name) ? DATA[name].slice() : [];
  }

  function all() {
    if (!FLAT) {
      FLAT = [];
      NAMES.forEach(function (n) { FLAT = FLAT.concat(DATA[n]); });
    }
    return FLAT.slice();
  }

  function random(opts) {
    var pool = (opts && opts.category) ? byCategory(opts.category) : all();
    if (!pool.length) return '';
    return pool[Math.floor(Math.random() * pool.length)];
  }

  return {
    data: DATA, categories: categories, byCategory: byCategory,
    all: all, random: random
  };
